item.text:
{
  "cases": [
    {
      "id": "P1A",
      "instrument_rationale": "The headline score describes one reported result. Missing execution history prevents assessment of repeatability and does not establish instability.",
      "probes": [
        {
          "id": "claim1",
          "label": "Not established",
          "quote": "gives no execution history",
          "reason": "The material does not establish whether repeated evaluations occurred."
        },
        {
          "id": "claim2",
          "label": "Not established",
          "quote": "one headline score of 75%",
          "reason": "One reported score supplies no evidence of variation across identical evaluations."
        }
      ]
    },
    {
      "id": "P1B",
      "instrument_rationale": "The execution record establishes that no repeats occurred. Repeatability remains unassessed; absence of repeats does not demonstrate unstable scores.",
      "probes": [
        {
          "id": "claim1",
          "label": "Contradicted",
          "quote": "no repeat evaluations were conducted",
          "reason": "The record explicitly rules out measuring changes across repeated evaluations."
        },
        {
          "id": "claim2",
          "label": "Not established",
          "quote": "this was the only evaluation performed",
          "reason": "A single evaluation cannot demonstrate instability across identical evaluations."
        }
      ]
    },
    {
      "id": "P2A",
      "instrument_rationale": "Six evaluations permit assessment against the report's explicit stability rule. Their two-percentage-point range satisfies that rule for this comparison.",
      "probes": [
        {
          "id": "claim1",
          "label": "Supported",
          "quote": "with identical inputs, settings and resources on six occasions",
          "reason": "The same AI and problems were evaluated repeatedly under identical reported conditions."
        },
        {
          "id": "claim2",
          "label": "Contradicted",
          "quote": "73, 74, 74, 75, 74 and 73 percent",
          "reason": "The range is two percentage points, within the permitted maximum of three."
        }
      ]
    },
    {
      "id": "P2B",
      "instrument_rationale": "The repeated evaluations document substantial variation under identical reported conditions. Their 31-percentage-point range fails the report's stability rule.",
      "probes": [
        {
          "id": "claim1",
          "label": "Supported",
          "quote": "with identical inputs, settings and resources on six occasions",
          "reason": "Repeated evaluations under the same reported conditions are explicitly documented."
        },
        {
          "id": "claim2",
          "label": "Supported",
          "quote": "51, 66, 79, 55, 82 and 62 percent",
          "reason": "The range is 31 percentage points, exceeding the permitted maximum of three."
        }
      ]
    },
    {
      "id": "P3A",
      "instrument_rationale": "Task and scoring descriptions explain benchmark content but supply no evidence about repeatability or mistakes in supplied answers.",
      "probes": [
        {
          "id": "claim1",
          "label": "Not established",
          "quote": "It gives no execution history",
          "reason": "Repeated identical-condition evaluations are not documented."
        },
        {
          "id": "claim2",
          "label": "Not established",
          "quote": "no findings about mistakes in the provided answers",
          "reason": "No answer mistakes are demonstrated; their absence is also not established."
        }
      ]
    },
    {
      "id": "P3B",
      "instrument_rationale": "The appendix provides setup information but adds no evidence about repeatability or answer correctness.",
      "probes": [
        {
          "id": "claim1",
          "label": "Not established",
          "quote": "It gives no execution history",
          "reason": "Installation details do not establish that repeated identical-condition evaluations were studied."
        },
        {
          "id": "claim2",
          "label": "Not established",
          "quote": "It reports no further evaluation results or examination of answers.",
          "reason": "Neither the original document nor the appendix demonstrates answer mistakes."
        }
      ]
    },
    {
      "id": "P4A",
      "instrument_rationale": "Independent examination supports a development review process. Missing agreement counts and error findings limit assessment of reviewer consistency and released-answer correctness.",
      "probes": [
        {
          "id": "claim1",
          "label": "Supported",
          "quote": "Two editors independently examined every question and supplied answer before release.",
          "reason": "Both questions and supplied answers underwent development review."
        },
        {
          "id": "claim2",
          "label": "Not established",
          "quote": "does not state whether mistakes were found or how many remained",
          "reason": "Review alone does not establish that all released answers are correct."
        }
      ]
    },
    {
      "id": "P4B",
      "instrument_rationale": "Development review is documented, but twelve released answers are explicitly wrong. These errors undermine scoring based on those answers; reviewer agreement is unreported.",
      "probes": [
        {
          "id": "claim1",
          "label": "Supported",
          "quote": "Two editors independently examined every question and supplied answer before release.",
          "reason": "Both benchmark questions and answers were examined during development."
        },
        {
          "id": "claim2",
          "label": "Contradicted",
          "quote": "twelve supplied answers as wrong in the released version",
          "reason": "The report explicitly identifies incorrect released answers."
        }
      ]
    },
    {
      "id": "P5A",
      "instrument_rationale": "The software rule establishes consistent marks for identical text. It does not establish that those marks are correct.",
      "probes": [
        {
          "id": "claim1",
          "label": "Not established",
          "quote": "No comparison of those marks with independently established correct marks is reported.",
          "reason": "The passage reports no such test, without establishing that none occurred."
        },
        {
          "id": "claim2",
          "label": "Not established",
          "quote": "identical text always receives the same mark",
          "reason": "Consistency of marking does not establish correctness for every response."
        }
      ]
    },
    {
      "id": "P5B",
      "instrument_rationale": "Comparison with independently correct marks provides a limited accuracy check. Two unresolved discrepancies document marking problems despite deterministic scoring.",
      "probes": [
        {
          "id": "claim1",
          "label": "Supported",
          "quote": "tested the software against independently established correct marks for 20 chosen responses",
          "reason": "The specified comparison was explicitly conducted."
        },
        {
          "id": "claim2",
          "label": "Contradicted",
          "quote": "Two marks differed and the discrepancies remain unresolved.",
          "reason": "The documented discrepancies conflict with correctness for every possible response."
        }
      ]
    },
    {
      "id": "P6A",
      "instrument_rationale": "The stated use is limited to the observed comparison. The reported counts directly support that use, without establishing performance elsewhere.",
      "probes": [
        {
          "id": "claim1",
          "label": "Supported",
          "quote": "identifying which system solved more of these 48 grid problems in this evaluation",
          "reason": "The supplied counts answer this narrowly stated question."
        },
        {
          "id": "claim2",
          "label": "Supported",
          "quote": "A solves 36 and B solves 24.",
          "reason": "A solved more of the evaluated problems under the reported fixed conditions."
        }
      ]
    },
    {
      "id": "P6B",
      "instrument_rationale": "The observed grid-task comparison supports a local ranking. Evidence connecting it to general intelligence across subjects and real-world settings is missing.",
      "probes": [
        {
          "id": "claim1",
          "label": "Not established",
          "quote": "No results from other tasks or settings are supplied.",
          "reason": "The narrow findings do not establish sufficiency for the broad stated use."
        },
        {
          "id": "claim2",
          "label": "Supported",
          "quote": "A solves 36 and B solves 24.",
          "reason": "The observed counts establish A's advantage on these evaluated grid problems."
        }
      ]
    },
    {
      "id": "P7A",
      "instrument_rationale": "The all-or-nothing rule matches the stated requirement to count completely correct grids. Excluding partial correctness is an explicit scope choice.",
      "probes": [
        {
          "id": "claim1",
          "label": "Supported",
          "quote": "one point for a completely correct grid and zero otherwise",
          "reason": "The rule implements the requirement to count only completely correct output grids."
        },
        {
          "id": "claim2",
          "label": "Contradicted",
          "quote": "partial correctness is deliberately outside this comparison",
          "reason": "Zero credit for partial correctness follows the stated requirement."
        }
      ]
    },
    {
      "id": "P7B",
      "instrument_rationale": "The all-or-nothing rule conflicts with the explicit requirement to credit correctly completed cells in partially correct grids.",
      "probes": [
        {
          "id": "claim1",
          "label": "Contradicted",
          "quote": "give a response credit for every correctly completed cell",
          "reason": "Awarding zero to partially correct grids fails this requirement."
        },
        {
          "id": "claim2",
          "label": "Supported",
          "quote": "including partially correct output grids",
          "reason": "The requirement explicitly includes partial grids, which the rule awards zero."
        }
      ]
    },
    {
      "id": "P8A",
      "instrument_rationale": "The study compares scores while changing instruction wording and holding other listed factors fixed. Without identical-instruction repeats, it cannot separately assess repeatability or fully isolate instruction effects from repeat variation.",
      "probes": [
        {
          "id": "claim1",
          "label": "Contradicted",
          "quote": "No evaluation repeats an identical instruction.",
          "reason": "Instruction wording changes, so conditions are not identical across evaluations."
        },
        {
          "id": "claim2",
          "label": "Supported",
          "quote": "each evaluation uses a differently worded instruction",
          "reason": "The study measures score changes across instruction variants, though attribution solely to wording is limited by the lack of identical-instruction repeats."
        }
      ]
    },
    {
      "id": "P8B",
      "instrument_rationale": "Repeated evaluations under identical reported conditions assess score consistency. They provide no comparison of different instructions.",
      "probes": [
        {
          "id": "claim1",
          "label": "Supported",
          "quote": "software, resources, problem order, settings and instruction are identical on every evaluation",
          "reason": "The study reports score changes while keeping the stated conditions identical."
        },
        {
          "id": "claim2",
          "label": "Contradicted",
          "quote": "No different instruction or presentation is studied.",
          "reason": "No instruction change was evaluated."
        }
      ]
    }
  ],
  "closing_note": "No separate review method was assigned; the supplied instrument guided the review. For P8A, measuring instruction effects means comparing instruction variants, without establishing that wording alone caused score changes."
}
